-- Update existing race's result_status
UPDATE race SET race_status = 'COMPLETED', result_status = 'COMPLETE' WHERE id IN (57, 58, 59, 61);
UPDATE race SET race_status = 'PLANNED', result_status = 'EMPTY' WHERE id IN (60);

